effect.shader:
float gmSkinMask(vec3 c){float cb=0.5-0.168736*c.r-0.331264*c.g+0.5*c.b;float cr=0.5+0.5*c.r-0.418688*c.g-0.081312*c.b;vec2 q=(vec2(cb,cr)-vec2(0.36,0.60))/vec2(0.11,0.16);return 1.0-smoothstep(skinRange,skinRange+0.35,dot(q,q));}
float gmRangeWeight(vec3 a,vec3 b){float sigma=mix(0.004,0.09,smoothness);return exp(-dot(a-b,a-b)/max(2.0*sigma*sigma,0.000001));}
void main(){vec2 uv=acScreenNorm;vec2 texSize=max(inputImg.size,vec2(1.0));vec2 texel=1.0/texSize;float radius=max(radiusPx,1.0);if(acPass==0){vec4 center=texture2DCv(inputImg.texture,uv);vec4 sum=vec4(0.0);float wsum=0.0;for(int i=-8;i<=8;i++){float f=float(i)/8.0;float spatial=exp(-0.5*f*f*4.0);vec4 s=texture2DCv(inputImg.texture,clamp(uv+vec2(f*radius*texel.x,0.0),0.0,1.0));float w=spatial*gmRangeWeight(center.rgb,s.rgb);sum+=s*w;wsum+=w;}gl_FragColor=sum/max(wsum,0.0001);return;}vec4 original=texture2DCv(inputImg.texture,uv);vec4 center=texture2DCv(smoothH.texture,uv);vec4 sum=vec4(0.0);float wsum=0.0;for(int i=-8;i<=8;i++){float f=float(i)/8.0;float spatial=exp(-0.5*f*f*4.0);vec4 s=texture2DCv(smoothH.texture,clamp(uv+vec2(0.0,f*radius*texel.y),0.0,1.0));float w=spatial*gmRangeWeight(center.rgb,s.rgb);sum+=s*w;wsum+=w;}vec3 smooth=sum.rgb/max(wsum,0.0001);vec3 detail=original.rgb-smooth;vec3 beauty=smooth+detail*detailPreserve;float mask=skinOnly?gmSkinMask(original.rgb):1.0;beauty.r+=warmth*0.05;beauty.b-=warmth*0.035;beauty+=brightness*0.12;float strength=smoothness*mask*mixAmount;gl_FragColor=vec4(mix(original.rgb,beauty,strength),original.a);}
